-- PostgreSQL version of SmartGatePlus [ml].[cycle_metadata] (MSSQL).
--   int IDENTITY(1,1) -> integer GENERATED BY DEFAULT AS IDENTITY (existing MSSQL ids can be copied over)
--   datetime          -> timestamp(3) without time zone (local time, millisecond precision)
--   bit               -> smallint limited to 0/1 (queries such as "use_for_training = 1" keep working)
--   float             -> double precision
-- The simulator fills: cycle_filename, recipe_name, start_time, end_time, set_cycle_time, created_at,
-- machine_id, plant_id, actual_cycle_time_seconds, bootstrap_flag (1 = historical, 0 = live)
-- and cycle_filepath. The other columns keep their defaults.

CREATE SCHEMA IF NOT EXISTS ml;

CREATE TABLE IF NOT EXISTS ml.cycle_metadata
(
    id                        integer GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1),
    cycle_filename            character varying(255) NOT NULL,
    recipe_name               character varying(100) NOT NULL,
    start_time                timestamp(3) without time zone NOT NULL,
    end_time                  timestamp(3) without time zone NOT NULL,
    set_cycle_time            integer NOT NULL,
    created_at                timestamp(3) without time zone NOT NULL,
    machine_id                integer NOT NULL,
    created_time              timestamp(3) without time zone DEFAULT now(),
    plant_id                  integer DEFAULT 1,
    sync_status               smallint DEFAULT 0,
    actual_cycle_time_seconds double precision,
    use_for_training          integer NOT NULL DEFAULT 0,
    bootstrap_flag            smallint DEFAULT 0,
    reconstruction_error      double precision,
    phase_detected            smallint NOT NULL DEFAULT 0,
    CONSTRAINT cycle_metadata_pkey PRIMARY KEY (id),
    CONSTRAINT cycle_metadata_sync_status_bit CHECK (sync_status IN (0, 1)),
    CONSTRAINT cycle_metadata_bootstrap_flag_bit CHECK (bootstrap_flag IN (0, 1)),
    CONSTRAINT cycle_metadata_phase_detected_bit CHECK (phase_detected IN (0, 1))
);

-- Not in the MSSQL table: the cycle file's path relative to the simulator's output folder (Output/Live).
ALTER TABLE ml.cycle_metadata ADD COLUMN IF NOT EXISTS cycle_filepath character varying(500);

